# Equivalence suite for the Julia port of dorado's routing core.
#
# All golden fixtures under `goldens/` are generated by the Python original
# (`goldens/generate_goldens.py`, run at a pinned dorado revision). Four gates:
#
#   1. init parity    — derived constructor state (u, v, velocity,
#                       velocity_angle, cell_type, weight) bit-identical to
#                       the Python Particles.__init__ output.
#   2. picker parity  — random_pick / steep_descent / random_pick_seed return
#                       the Python indices for recorded uniforms (including
#                       NaN rows, ties, all-zero rows, and the dead-end rule).
#   3. deterministic  — the steepest-descent walk, replaying the Python run's
#                       recorded raw uniform draws, reproduces the golden
#                       walk_data bit-exactly (indices exact, travel times
#                       bit-identical doubles).
#   4. stochastic     — the random-pick workloads under the package-managed
#                       RNG reproduce the golden summary statistics
#                       distributionally (appended-step counts exactly; visit
#                       histogram, displacement counts, and travel-time
#                       quantiles within tolerance bands). Bit-identical
#                       MT19937 streams are explicitly out of scope.

using Test
using JSON
using Random
using SHA
using StableRNGs

import Dorado
using Dorado: OptVar, Particles, npread, random_pick_seed, random_pick,
              steep_descent, generate_particles, run_iteration

GOLD = normpath(joinpath(@__DIR__, "..", "goldens", "goldens"))

"""RNG serving a recorded sequence of raw uniform draws (replay mode)."""
mutable struct ReplayRNG <: AbstractRNG
    values::Vector{Float64}
    i::Int
end
ReplayRNG(values::Vector{Float64}) = ReplayRNG(values, 0)
Base.rand(rng::ReplayRNG) = begin
    rng.i += 1
    (rng.i <= length(rng.values)) ||
        error("ReplayRNG exhausted: the walk drew more uniforms than recorded")
    return rng.values[rng.i]
end

"""JSON scalars to OptVar (nothing / Int64 / Float64 / String)."""
function to_optvar(v)
    v === nothing && return nothing
    v isa Bool && return Int64(v)
    v isa Integer && return Int64(v)
    v isa AbstractFloat && return Float64(v)
    v isa AbstractString && return String(v)
    error("unexpected JSON scalar type: $(typeof(v))")
end
to_optvars(v::AbstractVector) = Vector{OptVar}(to_optvar.(v))

"""Load a golden walk_data JSON into the port's walk-data representation."""
function load_walk(path::AbstractString)
    raw = JSON.parsefile(path)
    return Dict{String,Vector{Vector{OptVar}}}(
        k => Vector{Vector{OptVar}}(to_optvars.(v)) for (k, v) in raw)
end

"""Exact walk-data equality: indices and int flags exactly, doubles bit-for-bit."""
function walk_matches(got::Dict{String,Vector{Vector{OptVar}}},
                      want::Dict{String,Vector{Vector{OptVar}}})
    keys(got) == keys(want) || return false, "keys differ: " *
        "$(sort(collect(keys(got)))) vs $(sort(collect(keys(want))))"
    for k in keys(want)
        length(got[k]) == length(want[k]) ||
            return false, "$k: particle count $(length(got[k])) != $(length(want[k]))"
        for (i, g, w) in zip(eachindex(got[k]), got[k], want[k])
            length(g) == length(w) ||
                return false, "$k[$i]: step count $(length(g)) != $(length(w))"
            for (j, gv, wv) in zip(eachindex(g), g, w)
                if gv isa Float64 && wv isa Float64
                    isequal(gv, wv) ||  # bit-exact, NaN-aware
                        return false, "$k[$i][$j]: $(bitstring(gv)) != $(bitstring(wv))"
                else
                    gv == wv ||
                        return false, "$k[$i][$j]: $gv != $wv"
                end
            end
        end
    end
    return true, ""
end

"""Bit-identical or within `k` ULPs — the tolerance for libm-divergent
transcendentals (atan2). Same-sign floats compare monotonically by their
bit patterns; NaNs match NaNs; zeros must match exactly (sign included)."""
function within_ulp(a::Float64, b::Float64, k::Int=2)
    (isnan(a) && isnan(b)) && return true
    a == b && return true  # covers +0.0 == -0.0
    (iszero(a) || iszero(b)) && return false
    signbit(a) == signbit(b) || return false
    ia = reinterpret(Int64, a)
    ib = reinterpret(Int64, b)
    return abs(ia - ib) <= k
end

function hash_of(path::AbstractString)
    return bytes2hex(sha256(read(path)))
end

function relative_gap(a, b)
    a == b && return 0.0
    (a == 0 || b == 0) && return 1.0
    return abs(a - b) / max(abs(a), abs(b))
end

"""Summary statistics of a walk, mirroring the generator's visit_stats."""
function summary_stats(walk::Dict{String,Vector{Vector{OptVar}}}, shape)
    L, W = shape
    hist = zeros(Float64, L, W)
    dx_counts = Dict{Int,Int}()
    dy_counts = Dict{Int,Int}()
    n_entries = 0
    n_parked = 0
    for i in eachindex(walk["xinds"])
        px, py, times = walk["xinds"][i], walk["yinds"][i], walk["travel_times"][i]
        stranded = get(walk, "stranded", Vector{Vector{OptVar}}())
        stranded_i = i <= length(stranded) ? stranded[i] : nothing
        for t in eachindex(px)
            x, y = Int(px[t]), Int(py[t])
            hist[x+1, y+1] += 1.0
            n_entries += 1
            if stranded_i !== nothing && t <= length(stranded_i) &&
               stranded_i[t] == 1
                n_parked += 1
            end
            if t >= 2
                ddx = x - Int(px[t-1])
                ddy = y - Int(py[t-1])
                haskey(dx_counts, ddx) || (dx_counts[ddx] = 0)
                haskey(dy_counts, ddy) || (dy_counts[ddy] = 0)
                dx_counts[ddx] += 1
                dy_counts[ddy] += 1
            end
        end
    end
    final_times = sort([Float64(path[end]) for path in walk["travel_times"]])
    quantiles = Dict{String,Float64}()
    for q in (0.05, 0.25, 0.5, 0.75, 0.95)
        n = length(final_times)
        h = (n - 1) * q
        lo = floor(Int, h)
        hi = ceil(Int, h)
        quantiles[string(q)] = hi > lo ?
            final_times[lo+1] + (h - lo) * (final_times[hi+1] - final_times[lo+1]) :
            final_times[lo+1]
    end
    return Dict(
        "visit_hist" => hist,
        "n_entries" => n_entries,
        "parked_fraction" => n_parked / n_entries,
        "quantiles" => quantiles,
        "dx_counts" => dx_counts,
        "dy_counts" => dy_counts,
        "appended_steps" => sum(length(path) - 1 for path in walk["xinds"]),
    )
end

@testset "dorado-julia equivalence" begin

@testset "init parity" begin
    for name in ("rcm", "anuga")
        dir = joinpath(GOLD, "init_parity", "fixture_$name")
        hashes = JSON.parsefile(joinpath(dir, "hashes.json"))
        @testset "$name" begin
            p = Particles(dir)
            # velocity_angle goes through atan2, where NumPy's SIMD
            # implementation and Julia's libm can differ by 1 ULP; every
            # other field is add/mul/div/sqrt arithmetic and must be
            # bit-identical. The deterministic gate's rcm fixture is
            # unaffected (its velocity_angle is a single exact constant).
            for (field, fname, exact) in [
                ("u", "u.f64.npy", true), ("v", "v.f64.npy", true),
                ("velocity", "velocity.f64.npy", true),
                ("velocity_angle", "velocity_angle.f64.npy", false),
                ("cell_type", "cell_type.i64.npy", true),
                ("weight", "weight.f64.npy", true)]
                want = npread(joinpath(dir, fname))
                got = getproperty(p, Symbol(field))
                @test size(got) == size(want)
                if exact
                    # isequal: NaN weights compare equal bit-for-bit
                    # (plain == is false on NaN cells).
                    @test isequal(got, want)
                else
                    @test all(within_ulp(Float64(got[i]), Float64(want[i]), 2)
                              for i in eachindex(got))
                end
            end
            # The fixture directory itself must be untouched by the port.
            @test all(hashes[k] == hash_of(joinpath(dir, k))
                      for k in keys(hashes))
        end
    end
end

@testset "picker parity" begin
    # NaN appears legitimately inside recorded NaN-weight probe rows.
    rows = JSON.parsefile(joinpath(GOLD, "pick_goldens.json"); allownan=true)
    @test length(rows) == 125
    for (i, row) in enumerate(rows)
        u = Float64(row["u"])
        expected = Int(row["expected"])
        if row["kind"] == "random_pick"
            probs = Vector{Float64}(row["probs"])
            @test random_pick(StableRNG(1), probs; u=u) == expected
        elseif row["kind"] == "steep_descent"
            probs = Vector{Float64}(row["probs"])
            @test steep_descent(StableRNG(1), probs; u=u) == expected
        else  # random_pick_seed
            choices = Vector{Int64}(row["choices"])
            got = random_pick_seed(StableRNG(1), choices; u=u)
            @test got == expected
        end
    end
end

@testset "deterministic walk (replay gate)" begin
    dir = joinpath(GOLD, "deterministic")
    manifest = JSON.parsefile(joinpath(dir, "params.json"))
    rng = ReplayRNG(Vector{Float64}(manifest["uniforms"]))
    p = Particles(dir; rng=rng)
    @test p.steepest_descent == true
    @test p.diff_coeff == 0.0
    generate_particles(p, Int(manifest["Np_tracer"]),
                       Vector{Int64}(manifest["seed_xloc"]),
                       Vector{Int64}(manifest["seed_yloc"]);
                       method=String(manifest["method"]))
    for _ in 1:Int(manifest["iterations"])
        run_iteration(p)
    end
    want = load_walk(joinpath(dir, "walk_data.json"))
    ok, why = walk_matches(p.walk_data, want)
    @test ok  # failures print `why` below
    ok || println("deterministic mismatch: ", why)
    # The replay must consume exactly the recorded draws.
    @test rng.i == length(rng.values)
    # The dry blob must have exercised park stranding in the reference run.
    parked = sum(1 for path in p.walk_data["stranded"] for v in path if v == 1)
    @test parked > 0
end

@testset "stochastic distributional parity" begin
    for name in ("rcm", "anuga")
        dir = joinpath(GOLD, "init_parity", "fixture_$name")
        manifest = JSON.parsefile(joinpath(dir, "params.json"))
        iterations = name == "rcm" ? 20 : 50
        p = Particles(dir)  # package-managed LehmerRNG seeded from the manifest
        # Seed boxes mirror the bench_routing.py workloads: rcm rows 15-16 ×
        # cols 137-139, anuga rows 20-29 × cols 48-52.
        rows = name == "rcm" ? collect(15:16) : collect(20:29)
        cols = name == "rcm" ? collect(137:139) : collect(48:52)
        generate_particles(p, 500, rows, cols; method="random")
        for _ in 1:iterations
            run_iteration(p)
        end
        got = summary_stats(p.walk_data, size(p.depth))
        # Displacement bins are noisy per seed (a single bin can deviate
        # ~7% between independent runs), so compare against the mean of the
        # five golden seeds with a 10% band. Structural counts stay exact.
        wants = [JSON.parsefile(joinpath(GOLD, "stochastic",
                                         "$(name)_seed$(seed)_stats.json"))
                 for seed in 0:4]
        for want in wants
            @test got["appended_steps"] == want["appended_steps"]
            @test got["n_entries"] == want["n_entries"]
            @test got["parked_fraction"] == want["parked_fraction"]
        end
        # Quantiles are compared against the MEAN of the five golden seeds:
        # the walk itself is deterministic (manifest-seeded LehmerRNG), but
        # the golden per-seed spread at the 5% quantile reaches ~8% at N=500,
        # so a per-seed 5% gate would fail on golden-vs-golden noise.
        mean_q(q) = sum(w["quantiles"][q] for w in wants) / length(wants)
        for q in keys(wants[1]["quantiles"])
            @test relative_gap(got["quantiles"][q], mean_q(q)) < 0.05
        end
        for axis in ("dx_counts", "dy_counts")
            # JSON object keys are strings; mean the five golden seeds.
            golden_keys = parse.(Int, collect(keys(wants[1][axis])))
            mean_bin(k) = sum(w[axis][string(k)] for w in wants) / length(wants)
            @test sort(collect(keys(got[axis]))) == sort(golden_keys)
            for k in golden_keys
                @test relative_gap(got[axis][k], mean_bin(k)) < 0.10
            end
        end
        # Visit histogram: L1 distance within 10% of total entries, against
        # the seed-mean histogram. The golden stores the 2-D histogram as
        # nested row-major lists; flatten both sides in row-major order.
        want_hist = [sum(w["visit_hist"][x][y] for w in wants)
                     for x in 1:length(wants[1]["visit_hist"]),
                     y in 1:length(wants[1]["visit_hist"][1])] ./ length(wants)
        got_hist = [got["visit_hist"][x, y]
                    for x in 1:size(got["visit_hist"], 1),
                    y in 1:size(got["visit_hist"], 2)]
        l1 = sum(abs(g - w) for (g, w) in zip(got_hist, want_hist))
        # Band calibrated from golden seed-to-mean noise: golden seeds
        # themselves measure L1/n_entries of 0.065-0.079 (rcm) and
        # 0.150 max (anuga), so 10% fails golden-vs-golden on anuga.
        # 25% keeps ~1.7x headroom over the worst golden seed while still
        # catching a genuinely biased port.
        @test l1 < 0.25 * wants[1]["n_entries"]
    end
end

end # overall testset
